import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import * as config from '../../src/core/config-integrations.js';
import { getRegisteredDomainConfigSchemas, readDomainConfig, writeDomainConfig } from '../../src/core/domain-config.js';
import { loadPiclawEnvConfig } from '../../src/core/config-sources.js';
import { assertPathWithinTestFilesystemIsolation } from '../../scripts/test-filesystem-isolation.js';

const path = join(process.env.PICLAW_WORKSPACE!, '.piclaw/config.json');
assertPathWithinTestFilesystemIsolation(path, process.env, { allowRoot: false });
const original = readFileSync(path, 'utf8');
assert.equal('AGENT_LOG_CONFIG' in config, false);
assert.equal('getAgentLogConfig' in config, false);
const schema = getRegisteredDomainConfigSchemas().find(entry => entry.domain === 'logging')!;
assert(schema);
assert.deepEqual(Object.keys(schema.fields), ['level']);
assert.deepEqual(schema.retiredKeys, ['retentionMs', 'cleanupIntervalMs']);
const retired = ['PICLAW_AGENT_LOG_RETENTION_MS', 'PICLAW_AGENT_LOG_RETENTION_DAYS', 'PICLAW_AGENT_LOG_CLEANUP_INTERVAL_MS'];
const aliases = Object.values(schema.fields).flatMap(field => field.compatibilityEnv ?? []).map(alias => alias.envKey);
assert(retired.every(name => !aliases.includes(name)));
const value = readDomainConfig(schema, { configPath: path, env: process.env });
assert.deepEqual(value, { level: 'warn' });
assert.deepEqual(config.getLoggingConfig(), { level: 'warn' });
assert.equal(Object.isFrozen(config.getLoggingConfig()), true);
const dotenv = loadPiclawEnvConfig();
assert(retired.every(name => !(name in dotenv)));
assert.throws(() => writeDomainConfig(schema, { configPath: path, env: {} }, { retentionMs: 1 }), { message: 'Unknown domain config key: logging.retentionMs' });
assert.equal(readFileSync(path, 'utf8'), original);
const writableCopy = join(dirname(path), 'logging-copy.json');
writeFileSync(writableCopy, original);
assert.deepEqual(writeDomainConfig(schema, { configPath: writableCopy, env: {} }, { level: 'debug' }), { level: 'debug' });
const beforeLogging = JSON.parse(original).domains.logging;
const afterLogging = JSON.parse(readFileSync(writableCopy, 'utf8')).domains.logging;
for (const key of schema.retiredKeys!) assert.deepEqual(afterLogging[key], beforeLogging[key]);
assert.equal(readFileSync(path, 'utf8'), original);
const unknown = join(dirname(path), 'unknown.json');
writeFileSync(unknown, JSON.stringify({ domains: { logging: { unexpected: true } } }));
assert.throws(() => readDomainConfig(schema, { configPath: unknown, env: {} }), { message: 'Unknown persisted domain config key: logging.unexpected' });
console.log(JSON.stringify({ exportsRetired: true, aliasesRetired: true, legacyJsonAccepted: true, configBytesPreserved: true, loggingLevelPreserved: true, unknownKeysRefused: true }));
